<header class="admin-page-heading"><div><span class="eyebrow">بانک تجربه‌های مرشد</span><h1>مدیریت تجربه‌ها</h1><p class="muted">ثبت، تکمیل و بررسی تجربه‌ها در یک نگاه</p></div><a class="primary" href="<?= $this->h($this->url('/experience/edit')) ?>"><?= $this->icon('book') ?>ثبت تجربه جدید</a></header>
<nav class="admin-experience-tabs" aria-label="وضعیت تجربه‌ها"><a <?= empty($_GET['status'])?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/experiences')) ?>">همهٔ تجربه‌ها</a><?php foreach($stats as $stat): ?><a <?= ($_GET['status']??'')===$stat['status']?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/experiences?status='.$stat['status'])) ?>"><?= $this->status($stat['status']) ?><b><?= (int)$stat['total'] ?></b></a><?php endforeach; ?></nav>
<form method="get" class="card admin-experience-filters"><input type="hidden" name="r" value="/experiences"><div class="admin-filter-grid"><div class="filter-field admin-filter-query"><?= $this->field('q','جست‌وجوی تجربه','search',is_string($_GET['q']??null)?$_GET['q']:'',false) ?></div><div class="filter-field"><label for="review-status">وضعیت</label><select id="review-status" name="status"><option value="">همهٔ وضعیت‌ها</option><?php foreach(['draft','submitted','changes','approved','rejected'] as $key): ?><option value="<?= $key ?>" <?= ($_GET['status']??'')===$key?'selected':'' ?>><?= $this->status($key) ?></option><?php endforeach; ?></select></div><div class="filter-field"><label for="review-mentor">مرشد</label><select id="review-mentor" name="mentor_id"><option value="">همهٔ مرشدها</option><?php foreach($mentors as $m): ?><option value="<?= $this->h($m['user_id']) ?>" <?= ($_GET['mentor_id']??'')===$m['user_id']?'selected':'' ?>><?= $this->h($m['display_name']) ?></option><?php endforeach; ?></select></div><div class="filter-field"><label for="review-term">موضوع یا مسئله</label><select id="review-term" name="term_id"><option value="">همهٔ موضوع‌ها</option><?php foreach($terms as $term): ?><option value="<?= $this->h($term['id']) ?>" <?= ($_GET['term_id']??'')===$term['id']?'selected':'' ?>><?= $this->h($term['title']) ?></option><?php endforeach; ?></select></div></div><details class="admin-date-filter" <?= !empty($_GET['from'])||!empty($_GET['to'])?'open':'' ?>><summary><?= $this->icon('calendar') ?>محدودکردن بازهٔ زمانی</summary><div class="grid2"><div class="filter-field"><label for="review-from">از تاریخ</label><input id="review-from" type="date" name="from" value="<?= $this->h($_GET['from']??'') ?>"></div><div class="filter-field"><label for="review-to">تا تاریخ</label><input id="review-to" type="date" name="to" value="<?= $this->h($_GET['to']??'') ?>"></div></div></details><div class="admin-filter-footer"><a href="<?= $this->h($this->url('/experiences')) ?>">پاک کردن فیلترها</a><button class="primary">اعمال فیلتر</button></div></form>
<div class="results-heading section"><h2>فهرست تجربه‌ها</h2><div class="row small muted"><a href="<?= $this->h($this->url('/taxonomy')) ?>">موضوعات و مسائل</a><span>·</span><a href="<?= $this->h($this->url('/storefront')) ?>">چیدمان ویترین</a></div></div><div class="experience-admin-list"><?php foreach($rows as $row): ?><article class="admin-experience-row"><span class="admin-experience-symbol"><?= $this->icon('book') ?></span><div class="admin-experience-info"><div class="row"><span class="review-state state-<?= $this->h($row['status']) ?>"><?= $this->status($row['status']) ?></span><span class="small muted">نسخه <?= (int)$row['version_no'] ?></span></div><h2><?= $this->h($row['title']) ?></h2><p><?= $this->h($row['display_name']) ?> <span>·</span> <?= $row['public_version_id']?'دارای نسخهٔ عمومی':'منتشر نشده' ?></p><p class="small muted"><?= $this->h(['incomplete'=>'نیازمند تکمیل','ready'=>'آمادهٔ بررسی','rich'=>'پروندهٔ غنی'][$row['quality_level']??'']??'ساختار قدیمی') ?> <span>·</span> <time data-time="<?= (int)$row['created_at'] ?>"><?= gmdate('Y-m-d',$row['created_at']) ?></time></p></div><div class="admin-experience-actions"><a class="primary" href="<?= $this->h($this->url('/experience?id='.$row['id'])) ?>">پیش‌نمایش و بررسی</a><a class="secondary" href="<?= $this->h($this->url('/experience/edit?id='.$row['experience_id'])) ?>">ویرایش / تکمیل</a></div></article><?php endforeach; ?></div><?php if(!$rows): ?><div class="discovery-empty section"><?= $this->icon('book') ?><h2>تجربه‌ای با این فیلتر پیدا نشد</h2><p>بازه یا وضعیت دیگری انتخاب کن؛ می‌توانی همهٔ تجربه‌ها را هم ببینی.</p><a class="secondary" href="<?= $this->h($this->url('/experiences')) ?>">دیدن همهٔ تجربه‌ها</a></div><?php endif; ?>
